object Main {
  def main(args: Array[String]): Unit = {
    val nk = scala.io.StdIn.readLine().trim.split("\\s+")
    val n = nk(0).toInt
    val c = nk(1).toLowerCase
    val nama = (1 to n).map(_ => scala.io.StdIn.readLine().toLowerCase)
    println(nama.count(_.contains(c)))
  }
}
